good.c:
// NAME: Good C
// GAMES: MP1_USA,MP2_USA,MP3_USA
// EXECUTION: Direct
// PARAM: Number|coins
// PARAM: Space|target
// PARAM: Boolean|flag

extern void ShowPlayerCoinChange(int player, int amount);

int helper(int a) {
return a * 2 + flag;
}

void main() {
int x = helper(coins) + target;
if (x > 10) {
ShowPlayerCoinChange(0, target_chain_index);
}
}
