// PARAM: Number|coins
// PARAM: Space|target
// PARAM: Boolean|flag
// PARAM: Space[]|targets
// PARAM: +Number|amount

#include "ultra64.h"

void main() {
    int x = coins + amount + target + flag;
    if (x) {
        x = target_chain_index;
    }
}

